.huw-musical--workspace .huw-musical-menu-panel .huw-musical-links{display:block}
.huw-musical--workspace .huw-musical-menu-panel button,.huw-musical--workspace .huw-musical-menu-panel a{
 display:flex;align-items:center;justify-content:space-between;gap:12px;box-sizing:border-box;
 width:100%;min-height:36px;padding:5px 10px;border:0;border-radius:3px;
