/* Musical Studio 0.8: one coherent CutOut puppet workshop, not a second animation engine. */
.huw-musical.huw-musical--puppet-open:not(.huw-musical--focus){position:relative}
.huw-musical .huw-puppet-workshop{position:absolute;inset:0;z-index:500;display:flex;flex-direction:column;min-width:0;min-height:0;background:#111c2b;color:#eff4fc;font:12px/1.35 system-ui,-apple-system,sans-serif;outline:0}
.huw-puppet-workshop *{box-sizing:border-box}
.huw-puppet-workshop .huw-puppet-appbar{display:flex;align-items:center;gap:10px;min-height:47px;padding:5px 10px;background:#1b2a3d;border-bottom:1px solid #485c73}
.huw-puppet-workshop button{border:1px solid #506780;border-radius:5px;background:#2d465e;color:#edf6ff;font:inherit;cursor:pointer;min-height:28px;padding:5px 9px}
.huw-puppet-workshop button:focus-visible,.huw-puppet-workshop input:focus-visible,.huw-puppet-workshop select:focus-visible{outline:2px solid #89cfed;outline-offset:1px}
.huw-puppet-workshop button:hover{background:#345775}
.huw-puppet-workshop .huw-puppet-brand{display:flex;flex-direction:column;min-width:0;gap:1px;flex:1}
.huw-puppet-workshop .huw-puppet-brand strong{font-size:13px;letter-spacing:.01em}
.huw-puppet-workshop .huw-puppet-brand span{color:#afc5da;font-size:10px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.huw-puppet-workshop .huw-puppet-save{background:#21738c;border-color:#62bbd1;font-weight:650}
.huw-puppet-workshop .huw-puppet-layout{display:grid;grid-template-columns:minmax(145px,18%) minmax(0,1fr) minmax(200px,24%);flex:1;min-height:0;overflow:hidden}
.huw-puppet-workshop .huw-puppet-sidebar,.huw-puppet-workshop .huw-puppet-inspector{min-width:0;overflow-y:auto;background:#19283a;padding:10px;border-right:1px solid #40556e}
.huw-puppet-workshop .huw-puppet-inspector{border-right:0;border-left:1px solid #40556e;background:#1c2f44}
.huw-puppet-workshop h2,.huw-puppet-workshop h3{font-size:12px;font-weight:650;margin:0 0 10px;color:#f1f7fd}
.huw-puppet-workshop .huw-puppet-tree{display:flex;flex-direction:column;gap:2px}
.huw-puppet-workshop .huw-puppet-part{width:100%;text-align:left;border:0;min-height:24px;padding-top:5px;padding-bottom:5px;border-radius:4px;background:transparent;color:#c9d6e5;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.huw-puppet-workshop .huw-puppet-part.is-active{background:#315a75;color:#fff9e5;border-left:3px solid #f0bd68}
.huw-puppet-workshop .huw-puppet-center{display:flex;flex-direction:column;min-height:0;overflow:hidden;background:radial-gradient(circle at 50% 42%,#243347,#101a29 70%);padding:12px;align-items:stretch;justify-content:center}
.huw-puppet-workshop .huw-puppet-canvas{min-height:0;flex:1;display:flex;align-items:center;justify-content:center;touch-action:none}
.huw-puppet-workshop[data-workshop-kind="object"] .huw-puppet-canvas{border:1px solid #91a7b6;border-radius:9px;background-color:#f8fafb;background-image:linear-gradient(45deg,#e5eaee 25%,transparent 25%),linear-gradient(-45deg,#e5eaee 25%,transparent 25%),linear-gradient(45deg,transparent 75%,#e5eaee 75%),linear-gradient(-45deg,transparent 75%,#e5eaee 75%);background-size:24px 24px;background-position:0 0,0 12px,12px -12px,-12px 0}
.huw-puppet-workshop[data-workshop-kind="object"] .huw-puppet-canvas svg{background:transparent!important}
.huw-puppet-workshop .huw-puppet-canvas svg{display:block;width:100%;height:100%;max-width:100%;max-height:100%;touch-action:none;cursor:crosshair;overflow:visible}
.huw-puppet-workshop .huw-puppet-canvas .huw-cutout-part{cursor:grab}
.huw-puppet-workshop .huw-puppet-canvas .huw-cutout-part:active{cursor:grabbing}
.huw-puppet-workshop .huw-puppet-canvas .huw-cutout-joint{visibility:hidden;fill:#ffda76;stroke:#113047;stroke-width:3;pointer-events:all;cursor:move}
.huw-puppet-workshop .huw-puppet-canvas .huw-cutout-selected>.huw-cutout-joint{visibility:visible}
.huw-puppet-workshop .huw-puppet-canvas .huw-cutout-selected>g:first-child{filter:drop-shadow(0 0 2px #ffe2a1)}
.huw-puppet-workshop .huw-puppet-hint{font-size:11px;color:#a6bdd3;margin:10px auto 0;max-width:550px;text-align:center}
.huw-puppet-workshop .huw-puppet-fields{display:flex;flex-direction:column;gap:8px}
.huw-puppet-workshop .huw-puppet-section-title{font-size:11px;padding-top:7px;border-top:1px solid #465c70;color:#e3d3aa}
.huw-puppet-workshop .huw-puppet-field{display:flex;flex-direction:column;gap:3px;color:#b9cde0;font-size:11px}
.huw-puppet-workshop .huw-puppet-field input,.huw-puppet-workshop .huw-puppet-field select{background:#122239;color:#f5f8fc;border:1px solid #54718a;border-radius:4px;min-height:26px;padding:3px 6px;max-width:100%;width:100%;font:inherit}
.huw-puppet-workshop .huw-puppet-field input[type=color]{width:64px;padding:2px;cursor:pointer}
.huw-puppet-workshop .huw-puppet-presets{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:4px}
.huw-puppet-workshop .huw-puppet-presets button{font-size:11px;padding:5px}
.huw-puppet-workshop .huw-puppet-file{display:flex;flex-direction:column;gap:5px;padding:7px;border:1px dashed #67859d;border-radius:5px;cursor:pointer;font-size:11px}
.huw-puppet-workshop .huw-puppet-file input{max-width:100%;font-size:10px}
.huw-puppet-workshop .huw-puppet-footer{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:6px 11px;background:#1a293d;border-top:1px solid #485c73;font-size:10px;color:#a8c7d4;min-height:35px}
.huw-puppet-workshop .huw-puppet-library-toggle{display:flex;align-items:center;gap:5px;color:#e3effa;white-space:nowrap}
@media(max-width:730px){
 .huw-puppet-workshop .huw-puppet-layout{grid-template-columns:minmax(105px,22%) minmax(0,1fr);grid-template-rows:minmax(0,1fr) minmax(120px,36%)}
 .huw-puppet-workshop .huw-puppet-sidebar{grid-row:1;grid-column:1}
 .huw-puppet-workshop .huw-puppet-center{grid-row:1;grid-column:2;padding:5px}
 .huw-puppet-workshop .huw-puppet-inspector{grid-row:2;grid-column:1 / -1;border-left:0;border-top:1px solid #40556e;padding:8px}
 .huw-puppet-workshop .huw-puppet-fields{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:6px}
 .huw-puppet-workshop .huw-puppet-field{min-width:0}
 .huw-puppet-workshop .huw-puppet-brand span{font-size:9px}
 .huw-puppet-workshop .huw-puppet-appbar{gap:5px;padding:4px}
 .huw-puppet-workshop .huw-puppet-appbar button{padding:4px;font-size:10px}
}

/* Fyrtøjet demo: dedicated SFX and compact scene blocks */
.huw-musical-sfx-key{border-radius:50%;background:#d2a16c!important;color:#342033!important;rotate:0deg!important;font-size:10px!important;min-width:16px;max-width:20px;line-height:14px;}
.huw-musical-scene-clip{box-sizing:border-box;position:absolute;top:6px;height:23px;min-width:4px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;border:1px solid #48726c;background:#336d65;color:#f4fbf6;border-radius:3px;padding:2px 4px;font-size:10px;text-align:left;cursor:pointer;}
.huw-musical-scene-clip:nth-child(3n+1){background:#3b6775;}

.huw-musical-ruler-cursor::before{
 content:"";position:absolute;left:-3px;top:0;width:8px;height:8px;
 background:inherit;clip-path:polygon(0 0,100% 0,100% 50%,50% 100%,0 50%);
}
/* Keep the center of hollow noteheads clickable, including on ledger lines. */
.huw-musical-score-page .abcjs-notehead{pointer-events:bounding-box;}
.huw-musical-score-page .abcjs-ledger{pointer-events:none;}

/* Musical score as a two-way navigation surface for the master playhead. */
.huw-musical-score-page .huw-musical-score-note-target,
.huw-musical-score-page .abcjs-chord,
.huw-musical-score-page .abcjs-chord-text{cursor:pointer;}
.huw-musical--workspace .huw-musical-track[data-track-id="music:A"],
.huw-musical--workspace .huw-musical-track[data-track-id="music:B"]{min-height:43px;}
.huw-musical--workspace .huw-musical-track[data-track-id="music:B"] .huw-musical-lane-title{border-left-color:#bb97e4;}
.huw-musical--workspace .huw-musical-song-clip{touch-action:none;}

/* Direct manipulation (puppet and camera), editor-only SVG overlay. */
.huw-musical-transform-overlay{touch-action:none;user-select:none}
.huw-musical-transform-outline{fill:rgba(255,210,95,.05);stroke:#ffe29c;stroke-width:2.2;stroke-dasharray:8 5;cursor:move;vector-effect:non-scaling-stroke;pointer-events:all}
.huw-musical-transform-corner{fill:#fff8cf;stroke:#b16a27;stroke-width:2.3;vector-effect:non-scaling-stroke;cursor:nwse-resize;pointer-events:all}
.huw-musical-transform-rotate{fill:#8cddf5;stroke:#195779;stroke-width:2.3;vector-effect:non-scaling-stroke;cursor:crosshair;pointer-events:all}
.huw-musical-transform-skew{fill:#eb99ee;stroke:#694187;stroke-width:2;vector-effect:non-scaling-stroke;cursor:alias;pointer-events:all}
.huw-musical-transform-guide{stroke:#8cddf5;stroke-width:1.8;stroke-dasharray:3 4;pointer-events:none;vector-effect:non-scaling-stroke}
.huw-musical-transform-label{fill:#ffe2a6;paint-order:stroke;stroke:#121b2b;stroke-width:4;stroke-linejoin:round;font-size:13px;font-weight:700;pointer-events:none}
.huw-musical--workspace .huw-musical-transform-button[aria-pressed="true"]{background:#2a6884;border-color:#75c8e6;color:#fff}


/* Object-first selection: tapping the figure passes through the translucent
   bounding box, while handles and the dashed edge remain draggable. */
.huw-musical-transform-overlay[data-mode="figure"] .huw-musical-transform-outline{pointer-events:stroke}
.huw-musical--workspace .huw-musical-canvas svg{touch-action:none}
.huw-musical--workspace .huw-musical-canvas [data-cutout-id]{cursor:grab}
.huw-musical--workspace .huw-musical-canvas [data-cutout-id]:active{cursor:grabbing}
.huw-musical--workspace .huw-musical-transform-corner,.huw-musical--workspace .huw-musical-transform-rotate,.huw-musical--workspace .huw-musical-transform-skew{touch-action:none}

/* The timeline title is a second, touch-friendly stage selection surface.
   Double click / Enter marks the entire object, never just a limb. */
.huw-musical-select-object-title{cursor:pointer;touch-action:manipulation}
.huw-musical-select-object-title:hover{color:#e4f4ff;background:rgba(120,185,213,.14)}
.huw-musical-select-object-title:focus-visible{outline:2px solid #ffd37e;outline-offset:-2px}
.huw-musical-track.is-selected>.huw-musical-lane-title{box-shadow:inset 3px 0 0 #ffd37e}

/* One accessible object chooser rather than one timeline row per prop. */
.huw-musical-object-picker{position:relative;top:5px;margin-left:9px;min-height:25px;width:calc(100% - 18px);max-width:360px;color:#e9f4ff;background:#263f53;border:1px solid #55738c;border-radius:5px;font-size:12px;padding:3px 5px}

/* Subtitles are camera-fixed HUD, not transformed CutOut scene objects. */
.huw-musical-canvas{position:relative;}
.huw-musical-canvas>.huw-musical-caption-overlay{
 position:absolute;inset:0;z-index:22;display:flex;align-items:center;
 justify-content:flex-end;flex-direction:column;pointer-events:none;
 box-sizing:border-box;padding:0 5% 5%;text-align:center;
 color:#fff8ec;font-family:system-ui,-apple-system,sans-serif;
}
.huw-musical-caption-overlay .huw-musical-caption-line{
 max-width:98%;padding:.32em .68em;border-radius:6px;
 background:rgba(9,12,18,.66);font-size:clamp(12px,1.45vw,20px);
 line-height:1.45;font-weight:650;text-shadow:0 1px 3px #080a0e;
}
.huw-musical-caption-overlay .huw-musical-caption-cue{
 max-width:98%;margin-bottom:.4em;padding:.14em .55em;border-radius:5px;
 background:rgba(8,12,20,.48);font-size:clamp(10px,1.15vw,15px);
 color:#ffdfa2;font-weight:600;
}
.huw-musical-caption-overlay[hidden],.huw-musical-caption-overlay [hidden]{display:none!important;}

/* Musical inspector 0.9.2 — readable, context-specific, safely scrollable.
   All properties must fit on an iPad even in focus mode. */
.huw-musical--workspace .huw-musical-inspector-drawer{
 min-width:0;max-width:100%;overflow-x:hidden;overflow-y:auto;
 scrollbar-width:thin;scrollbar-color:#738ca5 #203247;
 overscroll-behavior-y:contain;
}
.huw-musical--workspace .huw-musical-inspector{
 display:block!important;min-width:0;width:100%;max-width:100%;
 padding:12px 13px 24px;overflow-wrap:anywhere;
}
.huw-musical--workspace .huw-musical-inspector>*{max-width:100%;margin:0 0 11px;}
.huw-musical--workspace .huw-musical-inspector>strong{display:block;font-size:13px;line-height:1.4;}
.huw-musical--workspace .huw-musical-inspector .huw-musical-property{
 display:flex;flex-direction:column;align-items:stretch;min-width:0;width:100%;
}
.huw-musical--workspace .huw-musical-inspector .huw-musical-property input,
.huw-musical--workspace .huw-musical-inspector .huw-musical-property select{
 width:100%;max-width:100%;box-sizing:border-box;min-width:0;
}
.huw-musical--workspace .huw-musical-inspector .huw-musical-mute{flex-direction:row;align-items:center;}
.huw-musical--workspace .huw-musical-inspector .huw-musical-mute input{width:auto;}
.huw-musical--workspace .huw-musical-inspector .huw-musical-key-actions{display:flex;gap:6px;flex-wrap:wrap;}
.huw-musical--workspace .huw-musical-inspector-type{
 display:inline-block;padding:3px 7px;background:#314f67;border:1px solid #52718a;
 color:#e6f6ff;border-radius:4px;font-size:11px;font-weight:700;
}
.huw-musical--workspace .huw-musical-inspector-help{
 line-height:1.55;color:#c4d5e4!important;font-size:11px;
 padding:8px;background:#1b3147;border-left:3px solid #79b8d4;border-radius:3px;
}
.huw-musical--workspace .huw-musical-inspector::after{
 content:'— Slut på egenskaber / End of properties —';display:block;
 margin-top:18px;padding:9px 0;border-top:1px solid #52667c;
 font-size:10px;color:#9eb2c7;text-align:center;
}
.huw-musical--workspace .huw-musical-inspector-heading strong{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
@media(min-width:1350px){
 .huw-musical--workspace.huw-musical--inspector-open .huw-musical-workbench{
  grid-template-columns:minmax(0,1fr) minmax(280px,330px);
 }
 .huw-musical--workspace.huw-musical--inspector-open .huw-musical-inspector-drawer{
  width:auto;min-width:0;
 }
}
@media(max-width:1349px){
 .huw-musical--workspace.huw-musical--inspector-open .huw-musical-inspector-drawer{
  width:min(330px,calc(100% - 12px));min-width:0;right:0;
 }
}

/* Shared full-size Script Workshop: scene notes are editor-only; the staged
   subtitles remain controlled by the common camera-fixed caption overlay. */
.huw-script-workshop{
 position:fixed;z-index:20000;left:2vw;right:2vw;top:3vh;bottom:3vh;
 background:#142338;color:#ecf4fb;border:1px solid #567089;
 border-radius:12px;box-shadow:0 14px 65px rgba(0,0,0,.65);
 display:flex;flex-direction:column;min-width:0;min-height:0;overflow:hidden;
 font-family:system-ui,-apple-system,sans-serif;font-size:13px;
}
.huw-script-workshop button,.huw-script-workshop input,.huw-script-workshop textarea{
 font:inherit;box-sizing:border-box;
}
.huw-script-workshop button{touch-action:manipulation;cursor:pointer}
.huw-script-header{display:flex;justify-content:space-between;align-items:center;gap:16px;
 padding:11px 15px;background:#1b3047;border-bottom:1px solid #435c76;}
.huw-script-header h2{font-size:17px;line-height:1.25;color:#f4f8ff;margin:0 0 3px;}
.huw-script-header p{margin:0;font-size:11px;color:#afc2d8;}
.huw-script-header-actions{display:flex;gap:8px;flex-wrap:wrap;}
.huw-script-primary,.huw-script-secondary,.huw-script-danger{
 padding:7px 11px;border-radius:6px;border:1px solid #627e96;background:#2d4865;color:#fff;white-space:nowrap;
}
.huw-script-primary{background:#257c96;border-color:#5aa8c3;font-weight:600;}
.huw-script-danger{background:#623341;border-color:#a25f69;}
.huw-script-common{display:flex;align-items:center;gap:10px;flex-wrap:wrap;padding:8px 12px;
 background:#1c2e42;border-bottom:1px solid #4b657f;}
.huw-script-common>strong{margin-right:10px;font-size:12px;}
.huw-script-field{display:flex;flex-direction:column;gap:4px;font-size:11px;color:#c2d5e5;min-width:0;}
.huw-script-common .huw-script-field{width:125px;}
.huw-script-common input[type=range]{width:100%;height:20px;accent-color:#5aaac0;}
.huw-script-caption-preview{flex:1;min-width:170px;display:flex;flex-direction:column;align-items:center;
 justify-content:flex-end;min-height:45px;background:#253346;border:1px solid #364d65;border-radius:5px;overflow:hidden;}
.huw-script-caption-sample{color:#fff8ed;text-align:center;padding:5px 10px;font-weight:650;border-radius:4px;}
.huw-script-columns{flex:1;display:grid;min-height:0;grid-template-columns:minmax(175px,22%) minmax(225px,34%) minmax(250px,44%);}
.huw-script-pane{min-height:0;min-width:0;overflow:auto;padding:11px;border-right:1px solid #3c536d;overscroll-behavior:contain;}
.huw-script-pane:last-child{border-right:0;}
.huw-script-pane h3{color:#e8f1f7;font-size:13px;margin:3px 0 10px;}
.huw-script-scenes,.huw-script-cue-list{display:flex;flex-direction:column;gap:5px;}
.huw-script-scene,.huw-script-cue{display:flex;align-items:flex-start;gap:7px;width:100%;text-align:left;
 border:1px solid transparent;border-radius:5px;padding:7px 8px;
 background:transparent;color:#d1e2f1;font-size:12px;}
.huw-script-scene:hover,.huw-script-cue:hover{background:#2a435b;}
.huw-script-scene.is-active,.huw-script-cue.is-active{background:#315a71;border-color:#63b3d0;}
.huw-script-scene-time,.huw-script-cue-time{font-variant-numeric:tabular-nums;color:#ffd89a;white-space:nowrap;font-weight:600;font-size:11px;}
.huw-script-cue-text{display:flex;flex-direction:column;gap:3px;line-height:1.32;min-width:0;}
.huw-script-cue-text small{font-size:10px;color:#acbfd1;}
.huw-script-pane-title{display:flex;align-items:center;justify-content:space-between;gap:8px;}
.huw-script-pane-title h3{margin:0;}
.huw-script-edit-pane .huw-script-field{margin:10px 0;}
.huw-script-selected{padding-bottom:9px;border-bottom:1px solid #3c5164;}
.huw-script-workshop input[type=number],.huw-script-workshop textarea{
 display:block;width:100%;min-width:0;background:#102235;color:#fff;
 border:1px solid #58728b;border-radius:5px;padding:8px;}
.huw-script-workshop textarea{resize:vertical;line-height:1.45;}
.huw-script-workshop input:focus-visible,.huw-script-workshop textarea:focus-visible,
.huw-script-workshop button:focus-visible{outline:2px solid #ffca73;outline-offset:2px;}
.huw-script-scene-notes{min-height:200px;}
.huw-script-range{display:grid;grid-template-columns:1fr 1fr;gap:10px;}
.huw-script-selected>button{margin-right:6px;margin-bottom:6px;}
.huw-script-notes-hint,.huw-script-placeholder{font-size:11px;color:#a2b5c8;line-height:1.4;}
.huw-script-footer{background:#1b3047;border-top:1px solid #425d75;display:flex;
 align-items:center;justify-content:space-between;gap:10px;padding:8px 13px;}
.huw-script-status{font-size:11px;color:#d1e0ee;}
.huw-musical-manuscript-button{background:#294b61!important;color:#e9f6ff!important;
 border:1px solid #658fa4!important;border-radius:6px!important;padding:5px 9px!important;}
@media(max-width:870px){
 .huw-script-workshop{left:1vw;right:1vw;top:1vh;bottom:1vh;}
 .huw-script-common{gap:6px;}
 .huw-script-common .huw-script-field{width:104px;}
 .huw-script-columns{grid-template-columns:minmax(130px,22%) minmax(170px,34%) minmax(190px,44%);}
 .huw-script-pane{padding:7px;}
}
@media(max-width:570px){
 .huw-script-columns{display:flex;flex-direction:column;overflow-y:auto;}
 .huw-script-pane{overflow:visible;border-right:0;border-bottom:1px solid #53687a;}
 .huw-script-scene-pane{max-height:150px;overflow:auto;}
 .huw-script-cue-pane{max-height:240px;overflow:auto;}
 .huw-script-edit-pane{flex:1;}
 .huw-script-caption-preview{min-width:100%;}
}
/* Native pickers retain their touch and keyboard interaction. Draw the closed
   control so WebKit cannot paint a light system bezel behind light text. */
.huw-musical--workspace :is(.huw-musical-filter,.huw-musical-object-picker,.huw-musical-inspector select,.huw-musical-playback-options select){
 -webkit-appearance:none;appearance:none;color-scheme:dark;
 color:#eef5fa;background-color:#23384c;padding-right:25px;
