","tags":"$:/tags/Stylesheet"},"$:/plugins/huwiki/musical/asset-library.js":{"title":"$:/plugins/huwiki/musical/asset-library.js","type":"application/javascript","text":"/*\
title: $:/plugins/huwiki/musical/asset-library.js
type: application/javascript
module-type: library
\*/
(function(){
'use strict';
var TAG='$:/tags/AniMus/Asset',CACHE='$:/AniMus/AssetCatalog',PREFIX='$:/AniMus/Library/',URL='https://forge.xn--mns-ula.dk/assets/animus/catalog.json';
var aliases={skov:'forest',orken:'desert',oerken:'desert',sol:'sun',mane:'moon',trae:'tree',hus:'house',huse:'house',bjerge:'mountain',bjerg:'mountain',hegn:'fence',baggrund:'background',baggrunde:'background',kulisse:'scenery',kulisser:'scenery',figur:'figure',figurer:'figure',dukke:'puppet',rekvisit:'prop',rekvisitter:'prop',mad:'food',vaerktoj:'tools',aeble:'apple',oejne:'eyes',ojne:'eyes',mund:'mouth',ansigt:'face',havn:'harbour',skib:'ship',graesk:'greek',kvinde:'female',mand:'male'};
function copy(v){return JSON.parse(JSON.stringify(v));}
function normal(s){return String(s||'').toLowerCase().replace(/æ/g,'ae').replace(/ø/g,'o').normalize('NFD').replace(/[\u0300-\u036f]/g,'');}
function valid(e){return !!(e&&typeof e.id==='string'&&/^[a-z0-9][a-z0-9/-]{0,200}$/.test(e.id)&&typeof e.name==='string'&&['figure','cutout','prop','scenery','background','face','sound'].indexOf(e.category)>=0&&Array.isArray(e.assets)&&e.assets.length<100&&(e.assets.length>0||Array.isArray(e.parts)&&e.parts.length>0||safeUrl(e.modelUrl))&&/^https:\/\//.test(e.source||''));}
function read(wiki,title){try{return JSON.parse(wiki.getTiddlerText(title,''));}catch(_bad){return null;}}
function localEntries(wiki){return (wiki.filterTiddlers?wiki.filterTiddlers('[all[tiddlers+shadows]tag['+TAG+']]'):(wiki.getTiddlersWithTag(TAG)||[])).map(function(t){return read(wiki,t);}).filter(valid);}
function entries(wiki,remote){var all={},cached=remote||read(wiki,CACHE)||{};(cached.entries||[]).filter(valid).forEach(function(e){all[e.id]=e;});localEntries(wiki).forEach(function(e){all[e.id]=e;});return Object.keys(all).map(function(id){return all[id];});}
function search(items,query,category,collection){var words=normal(query).split(/\s+/).filter(Boolean);return items.filter(function(e){if(category&&e.category!==category&&!(category==='figure'&&e.category==='cutout'))return false;if(collection&&e.collection!==collection)return false;var hay=normal([e.name,e.nameDa,e.category,e.collection,e.author,e.keywords,e.faceKind].join(' '));var tokens=hay.split(/[^a-z0-9]+/);return words.every(function(w){return tokens.some(function(t){return t.indexOf(w)===0||aliases[w]&&t.indexOf(aliases[w])===0;});});});}
function write(wiki,fields){wiki.addTiddler(new $tw.Tiddler(fields));}
function imageData(bytes){if(bytes.length<24||[137,80,78,71,13,10,26,10].some(function(v,i){return bytes[i]!==v;}))throw Error('Expected a PNG image');var view=new DataView(bytes.buffer,bytes.byteOffset,bytes.byteLength),w=view.getUint32(16),h=view.getUint32(20);if(!w||!h||w*h>40000000)throw Error('Image dimensions are too large');var chunks=[];for(var i=0;i<bytes.length;i+=8192)chunks.push(String.fromCharCode.apply(null,bytes.subarray(i,i+8192)));return {text:btoa(chunks.join('')),width:w,height:h};}
function safeUrl(s){return /^https:\/\/(?:forge\.xn--mns-ula\.dk|raw\.githubusercontent\.com)\//.test(String(s));}
async function download(a,fetcher,signal){if(!safeUrl(a.url))throw Error('Unsupported image source');var r=await fetcher(a.url,{credentials:'omit',signal:signal});if(!r.ok)throw Error('Image download failed: '+r.status);var length=Number(r.headers&&r.headers.get('content-length'));if(length>20000000)throw Error('Image exceeds 20 MB');var bytes=new Uint8Array(await r.arrayBuffer());if(bytes.length>20000000)throw Error('Image exceeds 20 MB');if(a.sha256&&typeof crypto!=='undefined'&&crypto.subtle){var digest=new Uint8Array(await crypto.subtle.digest('SHA-256',bytes));if(Array.from(digest).map(function(v){return v.toString(16).padStart(2,'0');}).join('')!==a.sha256)throw Error('Image checksum mismatch');}if(a.mime==='audio/wav'){if(bytes.length<44||String.fromCharCode.apply(null,bytes.subarray(0,4))!=='RIFF'||String.fromCharCode.apply(null,bytes.subarray(8,12))!=='WAVE')throw Error('Expected a WAV audio effect');var chunks=[];for(var i=0;i<bytes.length;i+=8192)chunks.push(String.fromCharCode.apply(null,bytes.subarray(i,i+8192)));return {text:btoa(chunks.join(''))};}return imageData(bytes);}
async function importEntry(wiki,entry,opts){
 opts=opts||{};if(!valid(entry))throw Error('Invalid catalogue entry');var saved=read(wiki,PREFIX+'items/'+entry.id);if(valid(saved))entry=saved;var next=copy(entry),pending=[];
 if(!next.parts&&next.modelUrl){if(!safeUrl(next.modelUrl))throw Error('Unsupported model source');var response=await (opts.fetcher||fetch)(next.modelUrl,{credentials:'omit',signal:opts.signal});if(!response.ok)throw Error('Material model unavailable');var modelText=await response.text();if(modelText.length>2000000)throw Error('Material model too large');
  if(next.modelSha256&&typeof crypto!=='undefined'&&crypto.subtle){var digest=new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(modelText)));if(Array.from(digest).map(function(v){return v.toString(16).padStart(2,'0');}).join('')!==next.modelSha256)throw Error('Material checksum mismatch');}
  var model=JSON.parse(modelText);if(!Array.isArray(model.parts)||!model.parts.length||model.parts.length>300)throw Error('Invalid material model');next.parts=model.parts;
 }
 for(var i=0;i<next.assets.length;i++){
  var a=next.assets[i],old=a.title&&wiki.getTiddler(a.title);
  if(old&&old.fields.type===(a.mime||'image/png')&&old.fields.text&&!old.fields._canonical_uri)continue;
  var title=PREFIX+'media/'+a.id,prior=wiki.getTiddler(title);if(prior&&prior.fields['animus-source-id']!==next.id)title=wiki.generateNewTitle(title);
  var data=await download(a,opts.fetcher||fetch,opts.signal);a.title=title;a.width=data.width;a.height=data.height;
  pending.push({title:title,type:a.mime||'image/png',text:data.text,tags:next.category==='sound'?'$:/tags/AniMus/AudioEffect':'','animus-effect-duration':next.category==='sound'?String(next.duration):'','animus-effect-name':next.name,'animus-effect-name-da':next.nameDa||next.name,'animus-effect-name-en':next.name,'animus-effect-icon':next.icon||'🔊','animus-effect-category':next.keywords||'','animus-effect-license':next.license,'animus-effect-source':next.source,'animus-source-id':next.id,'animus-source-url':a.url,'animus-author':next.author,'animus-license':next.license,'animus-license-url':next.licenseUrl||'','animus-source':next.source});
 }
 // Commit only after every dependency has arrived. A cancelled download leaves
 // neither a partial puppet nor a half-populated library entry.
 if(opts.signal&&opts.signal.aborted)throw Error('Cancelled');pending.forEach(function(f){write(wiki,f);});write(wiki,{title:PREFIX+'items/'+next.id,type:'application/json',tags:TAG,text:JSON.stringify(next)});return next;
}
function key(x,y){return {t:0,x:x||0,y:y||0,r:0,sx:1,sy:1,opacity:1,easing:'linear'};}
var serial=0;
function placeSound(film,entry,time){
 if(entry.category!=='sound'||entry.assets.length!==1||!entry.assets[0].title||!(entry.duration>0&&entry.duration<=120))throw Error('Invalid audio effect');
 var result=copy(film),start=Math.max(0,Math.min(Number(time)||0,Math.max(0,result.duration-.02))),m=result.musical||(result.musical={});if(!Array.isArray(m.audioClips))m.audioClips=[];
 m.audioClips.push({id:'audio-fx-'+Date.now().toString(36)+'-'+(++serial),asset:entry.assets[0].title,name:entry.name,icon:entry.icon||'🔊',effectId:entry.id,kind:'effects',start:start,offset:0,duration:Math.min(entry.duration,result.duration-start),sourceDuration:entry.duration,volume:.7,reverb:0,muted:false});return result;
}
function place(scene,entry,options){
 options=options||{};if(!valid(entry))throw Error('Invalid library entry');var target=copy(scene),width=Number(target.width)||960,height=Number(target.height)||540;
