.huw-musical-effects-backdrop{position:fixed;inset:0;z-index:100001;background:rgba(0,0,0,.26);display:flex;align-items:center;justify-content:center;padding:12px}
.huw-musical-effects-dialog{box-sizing:border-box;width:420px;max-width:100%;max-height:75vh;overflow:auto;background:<<colour tiddler-background>>;color:<<colour foreground>>;border:1px solid <<colour tiddler-border>>;border-radius:9px;box-shadow:0 8px 28px #0004;padding:12px}
.huw-musical-effects-heading{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:8px}
.huw-musical-effects-heading button{font-size:1.3em;line-height:1;padding:3px 8px}
.huw-musical-effects-search{box-sizing:border-box;width:100%;margin-bottom:8px}
.huw-musical-effects-toolbar{display:flex;gap:6px;flex-wrap:wrap;margin-bottom:8px;align-items:center}
.huw-musical-effect-import{position:relative;overflow:hidden;display:inline-block;border:1px solid <<colour button-border>>;border-radius:4px;padding:3px 8px;cursor:pointer}
.huw-musical-effect-import input{position:absolute;inset:0;opacity:0;cursor:pointer;width:100%}
.huw-musical-effects-library{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:6px}
.huw-musical-effects-tile{position:relative;border:1px solid <<colour tiddler-border>>;border-radius:6px;overflow:hidden}
.huw-musical-effect-choice{box-sizing:border-box;display:flex;flex-direction:column;align-items:center;gap:4px;width:100%;min-height:78px;padding:6px 6px 22px!important;white-space:normal;overflow-wrap:anywhere;border:0!important}
.huw-musical-effect-choice[aria-pressed="true"]{box-shadow:inset 0 0 0 2px <<colour primary>>}
.huw-musical-effect-symbol{font-size:25px;line-height:1.3}
.huw-musical-effect-listen{position:absolute;bottom:1px;right:3px;min-width:23px;padding:1px 5px!important;font-size:12px}
.huw-musical-effects-empty{grid-column:1/-1}
.huw-musical-effects-status{display:block;font-size:.85em;overflow-wrap:anywhere;margin-bottom:5px}
