.huw-musical-cue-score-time{font-variant-numeric:tabular-nums;opacity:.75}
.huw-musical-cue-score-row.huw-musical-note-active{background:#f6dfa8!important;color:#24211c!important;border-color:#8b6a2c!important}
.huw-musical-cue-score-row:focus-visible{outline:3px solid #a87a2c;outline-offset:2px}
