.huw-musical-face-panel{flex:0 0 auto;min-width:0;padding:9px 12px 10px;background:#eaf1f5;color:#183345;border-top:1px solid #71899b;border-bottom:1px solid #7b91a1;font:13px/1.35 system-ui,-apple-system,sans-serif}
