.huw-musical-face-tabs{display:flex;gap:3px;padding:3px;background:#d2dfe7;border-radius:9px}
.huw-musical-face-panel button,.huw-face-workshop button{font:inherit;line-height:1.25;cursor:pointer;touch-action:manipulation;border:1px solid #8ca4b5;border-radius:7px;background:#fff;color:#193747;padding:9px 11px;min-height:44px;box-sizing:border-box}
.huw-musical-face-panel button:focus-visible,.huw-musical-face-panel summary:focus-visible,.huw-face-workshop button:focus-visible{outline:3px solid #c06c12;outline-offset:2px}
