.huw-musical-face-panel .huw-musical-face-tab[aria-selected=true]{background:#fff;border-color:#548a9d;box-shadow:0 1px 4px #143d4f20}
.huw-musical-face-status{display:inline-flex;align-items:center;border-radius:20px;padding:5px 9px;background:#d3e8df;color:#23513e;white-space:nowrap;font-size:12px;font-weight:650}
