.huw-musical-face-choices{display:flex;align-items:stretch;gap:8px;overflow:auto;min-width:0;padding:4px 3px 7px;overscroll-behavior-x:contain;scrollbar-width:thin;scroll-snap-type:x proximity}
.huw-musical-face-panel .huw-musical-face-choice{flex:0 0 106px;display:flex;flex-direction:column;gap:6px;align-items:center;min-height:114px;padding:6px;scroll-snap-align:start;border-width:2px;background:#fbfdff}
