.huw-face-workshop-preview svg{pointer-events:auto}
.huw-musical-face-choice-name{display:block;text-align:center;font-size:12px;font-weight:650;max-width:100%;overflow-wrap:anywhere}
.huw-musical-face-preview-missing{display:flex;align-items:center;justify-content:center;height:100%;color:#56717e}
.huw-musical-face-footer{display:flex;gap:10px;align-items:center;min-width:0;padding-top:3px}
.huw-musical-face-copy{flex:1;min-width:100px}
.huw-musical-face-context{margin:0 0 3px;font-weight:650;color:#254f61}
.huw-musical-face-line{margin:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:#425e6c;font-size:12px}
.huw-musical-face-actions{display:flex;align-items:center;gap:6px;flex-wrap:wrap}
