.huw-musical-face-more{position:relative}
.huw-musical-face-more summary{display:flex;align-items:center;min-height:44px;cursor:pointer;padding:0 8px;white-space:nowrap;list-style:none;color:#496477}
.huw-musical-face-more summary:after{content:' ▾';padding-left:4px}
.huw-musical-face-more[open] .huw-musical-face-hold{position:absolute;bottom:100%;right:0;min-width:165px;box-shadow:0 5px 24px #14324730;z-index:3;white-space:nowrap}
.huw-musical-face-empty{margin:10px}
.huw-musical-face-announcement{position:absolute;width:1px;height:1px;padding:0;overflow:hidden;clip-path:inset(50%);white-space:nowrap}
.huw-musical-stage:fullscreen .huw-musical-face-panel,.huw-musical-stage--expanded .huw-musical-face-panel{flex:0 0 auto;max-height:48dvh;overflow:auto;margin-top:6px;border-radius:6px}
.huw-face-workshop{position:fixed;inset:2vh 2vw;z-index:2147482200;display:flex;flex-direction:column;overflow:hidden;background:#f2f6f8;color:#183345;border:1px solid #a4bac8;border-radius:12px;box-shadow:0 15px 90px #04152770;font:14px/1.4 system-ui,-apple-system,sans-serif}
