.huw-face-sound-copy{display:flex;flex-direction:column;min-width:0;font-size:11px;line-height:1.35}
.huw-face-sound-copy strong{font-size:13px}
.huw-face-sound-choice{color:#365b70;font-weight:600}
.huw-face-sound-original{color:#617984;font-size:10px}
.huw-face-sound[data-face-custom=true] .huw-face-sound-choice{color:#146b52}
.huw-face-workshop-editing{min-width:0;display:flex;flex-direction:column}
.huw-face-workshop .huw-musical-face-panel{border-top:0;padding:14px;background:#f2f6f8}
.huw-face-workshop .huw-musical-face-choices{flex-wrap:wrap;overflow:visible;gap:10px}
.huw-face-workshop .huw-musical-face-choice{flex-basis:125px;min-height:137px}
.huw-face-workshop .huw-musical-face-thumbnail{width:106px;height:96px}
.huw-face-workshop .huw-musical-face-footer{align-items:flex-start;flex-direction:column}
.huw-face-workshop .huw-musical-face-line{white-space:normal;line-height:1.5}
.huw-face-workshop-history{padding:16px;min-height:80px}
.huw-face-workshop .huw-face-history-key{display:flex;align-items:center;gap:12px;width:100%;text-align:left;margin:6px 0;background:#fff}
.huw-face-history-thumbnail{display:block;flex:0 0 54px;height:54px;overflow:hidden;border-radius:5px;background:#dbe5e9}
.huw-face-history-key strong{flex:0 0 52px;color:#176c83}
@media(max-width:760px){
 .huw-musical-face-panel{padding:7px 8px}.huw-musical-face-top{gap:5px}.huw-musical-face-title{max-width:120px;font-size:12px}.huw-musical-face-status{font-size:11px;padding:4px 7px}.huw-musical-face-panel .huw-musical-face-tab{min-width:59px;padding:8px}
