","module-type":"library"},"$:/plugins/huwiki/musical/figure-panel.css":{"title":"$:/plugins/huwiki/musical/figure-panel.css","type":"text/css","text":"/* A live, isolated view of one current figure inside the shared workshop. */
.huw-musical-figure-panel{display:flex;flex:1 1 auto;flex-direction:column;min-width:0;min-height:0;height:100%;padding:10px 12px;box-sizing:border-box;background:#eef3f6;color:#183345;font:13px/1.35 system-ui,-apple-system,sans-serif}
