.huw-musical-figure-header{display:flex;align-items:center;gap:9px;flex-wrap:wrap;flex:0 0 auto;margin-bottom:8px;min-width:0}
.huw-musical-figure-title{font-size:16px}
.huw-musical-figure-selected-label{color:#36546a}
.huw-musical-figure-time{font-variant-numeric:tabular-nums;color:#526575;white-space:nowrap}
.huw-musical-figure-fit{margin-left:auto;flex:0 0 auto}
