.huw-musical-figure-panel button:focus-visible{outline:3px solid #c06c12;outline-offset:2px}
.huw-musical-figure-body{display:flex;flex:1 1 auto;gap:10px;min-height:0;min-width:0;overflow:hidden}
.huw-musical-figure-canvas{display:flex;position:relative;flex:1 1 auto;min-height:220px;min-width:0;border:1px solid #9aaeba;border-radius:10px;overflow:hidden;touch-action:none;user-select:none;-webkit-user-select:none;background:radial-gradient(ellipse at 50% 42%,#fff 0,#e4edf3 76%)}
.huw-musical-figure-panel[data-figure-kind="object"] .huw-musical-figure-canvas{background-color:#f8fafb;background-image:linear-gradient(45deg,#e5eaee 25%,transparent 25%),linear-gradient(-45deg,#e5eaee 25%,transparent 25%),linear-gradient(45deg,transparent 75%,#e5eaee 75%),linear-gradient(-45deg,transparent 75%,#e5eaee 75%);background-size:24px 24px;background-position:0 0,0 12px,12px -12px,-12px 0}
.huw-musical-figure-preview{display:block!important;width:100%!important;height:100%!important;min-height:220px;max-height:none!important;overflow:visible;touch-action:none;background:transparent!important}
.huw-musical-figure-preview .huw-cutout-part{cursor:grab}
.huw-musical-figure-preview [opacity="0"],.huw-musical-figure-preview [opacity="0"] *{pointer-events:none!important}
.huw-musical-figure-parts{display:flex;flex-direction:column;gap:5px;flex:0 0 clamp(140px,21%,220px);min-height:0;overflow:auto;overscroll-behavior:contain;padding:2px 5px 4px 2px;scrollbar-width:thin}
.huw-musical-figure-part{text-align:left;flex:0 0 auto;overflow-wrap:anywhere}
.huw-musical-figure-part[aria-pressed="true"]{border-color:#bd751e!important;background:#fff0d8!important;box-shadow:inset 3px 0 #bd751e}
.huw-musical-figure-overlay{pointer-events:none}
.huw-musical-figure-outline{fill:none;stroke:#b46b13;stroke-width:2;stroke-dasharray:6 4;vector-effect:non-scaling-stroke;pointer-events:none}
.huw-musical-figure-guide{stroke:#4384aa;stroke-width:1.5;stroke-dasharray:4 3;vector-effect:non-scaling-stroke;pointer-events:none}
.huw-musical-figure-pivot{fill:#fff;stroke:#b46b13;stroke-width:2;vector-effect:non-scaling-stroke;pointer-events:none}
.huw-musical-figure-rotate{fill:#207aa8;stroke:#fff;stroke-width:2;vector-effect:non-scaling-stroke;pointer-events:all;cursor:grab;touch-action:none}
.huw-musical-figure-hint{flex:0 0 auto;margin:7px 0 0;font-size:12px;color:#415b6b}
.huw-musical-figure-status{flex:0 0 auto;font-size:12px;color:#326145;min-height:0}
.huw-musical-figure-status:empty{display:none}
.huw-musical-object-visibility{display:flex;align-items:center;gap:10px;flex:0 0 auto;flex-wrap:wrap;margin-top:7px;padding:6px 8px;border:1px solid #c39d5b;border-radius:7px;background:#fff5df;color:#62431a}
.huw-musical-object-reveal{margin-left:auto}
.huw-musical-object-appearance,.huw-musical-object-properties{flex:0 0 auto}
@media(max-width:640px){.huw-musical-figure-panel{padding:8px}.huw-musical-figure-body{gap:6px}.huw-musical-figure-parts{flex-basis:122px}.huw-musical-figure-selected-label{flex:1 1 auto}.huw-musical-figure-time{font-size:12px}.huw-musical-figure-fit{padding:7px!important}.huw-musical-figure-hint{font-size:11px}}
.huw-musical-figure-parts[hidden],.huw-musical-figure-parts-toggle[hidden]{display:none}
.huw-musical-figure-parts-toggle::after{content:' ▾'}
.huw-musical-figure-parts-toggle[aria-expanded=true]::after{content:' ▴'}

.huw-musical-figure-zoom{display:flex;align-items:center;gap:8px;flex:0 0 auto;min-width:0;margin:0 0 8px;font-size:14px}
.huw-musical-figure-zoom button{padding:4px 10px;min-width:44px;font-size:20px}
.huw-musical-figure-zoom-range{width:clamp(100px,22vw,230px);max-width:100%;min-width:60px;margin:0;accent-color:#207aa8;cursor:pointer;flex:0 1 230px;height:32px}
.huw-musical-figure-zoom-value{min-width:4.5em;font-variant-numeric:tabular-nums;color:#36546a}
.huw-musical-figure-panel button:disabled{opacity:.45;cursor:default}
