.huw-script-lipsync-controls select:disabled,.huw-script-lipsync-controls input:disabled{opacity:.5}
.huw-script-lipsync-hint,.huw-script-lipsync-warning{margin:.55rem 0 0;font-size:.8rem;line-height:1.45}
