","module-type":"library"},"$:/plugins/huwiki/musical/narration.css":{"title":"$:/plugins/huwiki/musical/narration.css","type":"text/css","text":".huw-narration-workshop{position:fixed;inset:20px;z-index:21000;display:flex;flex-direction:column;min-width:0;min-height:0;background:#f4f7f9;color:#223443;border:1px solid #91a6b4;border-radius:14px;box-shadow:0 14px 60px #08132166;font:14px/1.45 system-ui,sans-serif;overflow:hidden}
