.huw-narration-header{display:flex;justify-content:space-between;align-items:center;gap:16px;padding:16px 20px;border-bottom:1px solid #bdcbd4;background:#fff}.huw-narration-header p{font-size:12px;color:#536b7b;margin:5px 0 0}.huw-narration-actions{display:flex;gap:8px;flex-shrink:0}
