.huw-narration-body{display:grid;grid-template-columns:minmax(260px,1.1fr) minmax(200px,.8fr) minmax(250px,1fr);flex:1;min-height:0;overflow:hidden}.huw-narration-body>section{padding:18px;overflow:auto;min-width:0;border-right:1px solid #c9d5dd}.huw-narration-body>section:last-child{border-right:0}.huw-narration-list-pane{background:#eaf0f4}.huw-narration-inspector{background:#fff}
